<script setup lang="ts">
import { computed, ref } from 'vue'
import FlowChart from './FlowChart.vue'
import { useTourism } from './useTourism'
const { dashboard, content, connected, stale, error, staticDemo } = useTourism()
const activeNews = ref<string | null>(null)
const latest = computed(() => dashboard.value?.latest)
const today = computed(() => dashboard.value?.sameDay ? latest.value : null)
const load = computed(() => today.value && dashboard.value ? Math.round(today.value.occupancy / dashboard.value.capacity * 100) : null)
const crowd = computed(() => load.value === null ? '等待数据' : load.value >= 80 ? '较拥挤' : load.value >= 60 ? '适中' : '较舒适')
const format = (value?: number | null) => value == null ? '—' : value.toLocaleString('zh-CN')
const updateTime = computed(() => latest.value ? new Date(latest.value.sampledAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) : '尚未收到上报')
const source = computed(() => staticDemo ? '网页模拟演示' : latest.value?.source === 'ue-simulation' ? 'UE 5.8 模拟' : latest.value ? '本地模拟器' : '等待 UE 上报')
</script>
<template>
  <header class="site-header"><a href="#" class="brand"><span class="brand-mark">山</span><span>张家界<small>智慧游览 · ZHANGJIAJIE</small></span></a><nav aria-label="页面导航"><a href="#flow">客流趋势</a><a href="#booking">景点预约</a><a href="#news">文旅资讯</a></nav><span class="demo-pill">模拟演示</span></header>
  <main>
    <section class="hero"><div class="mountains" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="hero-copy"><span class="eyebrow">山水有约 · 从容出发</span><h1>看见人流，<br>遇见好风景。</h1><p>出发前了解景区动态，选择适合自己的游览时段。</p><a class="hero-button" href="#booking">查看景点预约 <span>↗</span></a></div><div class="hero-caption">张家界 · 景区数字孪生演示<small>客流、预约、天气与资讯均为模拟数据</small></div></section>
    <div class="status-bar" role="status"><span><i :class="['status-dot', { online: connected && !stale }]"></i>{{ source }} · {{ staticDemo ? '未连接 UE' : !latest ? '等待首次数据' : stale ? '数据已过期' : connected ? '同步中' : '正在重连' }}</span><span>{{ staticDemo ? '演示更新' : '最后采集' }}：{{ updateTime }}</span></div>
    <p v-if="error" class="error-banner" role="alert">{{ error }} 已收到的数据会保留，不会自动替换为模拟器数据。</p>
    <section class="stats" aria-label="今日景区概况"><article class="stat"><span>今日累计入园</span><strong>{{ format(today?.enteredToday) }}<small>人次</small></strong><p>景区闸机模拟汇总</p></article><article class="stat"><span>今日累计出园</span><strong>{{ format(today?.exitedToday) }}<small>人次</small></strong><p>统计日期 {{ dashboard?.day || '—' }}</p></article><article class="stat"><span>当前在园估计</span><strong>{{ format(today?.occupancy) }}<small>人</small></strong><p>模拟进出净额，非去重人数</p></article><article class="stat crowd"><span>当前游览舒适度</span><strong>{{ crowd }}</strong><p>模拟承载率 {{ load === null ? '—' : load + '%' }} · 非官方限流标准</p></article></section>
    <div class="main-grid"><section id="flow" class="panel trend-panel"><div class="panel-heading"><div><span class="eyebrow">VISITOR FLOW</span><h2>客流趋势</h2></div><span class="subtle-tag">今日 · 5 分钟粒度</span></div><FlowChart :points="dashboard?.trend || []"/><p class="chart-note">{{ staticDemo ? '此曲线由浏览器模拟生成，不代表真实历史或未来预测。' : !dashboard?.trend.length ? '等待采集数据，曲线将在上报后逐步形成。此图不提供未来预测。' : '每 5 分钟汇总进出人次；首次区间和中断区间不填补。此图不提供未来预测。' }}</p></section>
    <aside class="panel weather-panel"><span class="eyebrow">WEATHER</span><h2>山间天气</h2><div class="weather-symbol" aria-hidden="true">☁</div><strong>{{ content ? content.weather.temperature + '°' : '—' }}</strong><p>{{ content?.weather.condition || '等待数据' }} <span>{{ content?.weather.range }}</span></p><dl><div><dt>相对湿度</dt><dd>{{ content ? content.weather.humidity + '%' : '—' }}</dd></div><div><dt>游览准备</dt><dd>雨具 · 防滑鞋</dd></div></dl><small>{{ content?.weather.note || '天气模块尚未加载' }}</small></aside></div>
    <section id="booking" class="booking-section"><div class="section-heading"><div><span class="eyebrow">PLAN YOUR VISIT</span><h2>景点预约情况</h2></div><span>今日余量 · 示例数据</span></div><div class="attraction-grid"><article v-for="(place, index) in content?.attractions || []" :key="place.id" class="attraction"><div :class="['place-art', 'art-' + index]" aria-hidden="true"><span>0{{ index + 1 }}</span></div><div class="place-body"><div class="place-title"><h3>{{ place.name }}</h3><span :class="{ tight: place.remaining / place.total < 0.1 }">{{ place.status }}</span></div><p>{{ place.description }}</p><div class="remaining"><span>剩余名额 <b>{{ format(place.remaining) }}</b></span><small>模拟总量 {{ format(place.total) }}</small></div><div class="capacity-track"><i :style="{ width: place.remaining / place.total * 100 + '%' }"></i></div></div></article></div><div class="booking-channel"><div><strong>通过官方小程序完成预约</strong><p>本站展示模拟余量，实际余量及预约结果以官方渠道为准。</p></div><a v-if="content?.bookingUrl" :href="content.bookingUrl" target="_blank" rel="noopener noreferrer" class="primary-button">前往预约小程序 ↗</a><button v-else disabled>小程序入口待配置</button></div></section>
    <section id="news" class="panel news-panel"><div class="panel-heading"><div><span class="eyebrow">LATEST UPDATES</span><h2>文旅资讯</h2></div><span class="subtle-tag">演示资讯</span></div><p v-if="!content" class="chart-note">等待资讯加载</p><article v-for="item in content?.news || []" :key="item.id" class="news-row"><button :aria-expanded="activeNews === item.id" @click="activeNews = activeNews === item.id ? null : item.id"><span class="news-tag">{{ item.tag }}</span><span class="news-title">{{ item.title }}</span><span class="news-arrow">{{ activeNews === item.id ? '−' : '+' }}</span></button><div v-if="activeNews === item.id" class="news-detail"><p>{{ item.detail }}</p><small>来源：{{ item.source }} · 示例内容，无真实发布时间</small></div></article></section>
  </main><footer><span>张家界 · 智慧游览</span><span>{{ staticDemo ? 'GitHub Pages 网页模拟演示 · 未连接 UE' : '本地演示项目 / UE 5.8 数据接入' }} · 非官方旅游服务</span></footer>
</template>
